"""C4: token checks (pure) and the verify endpoint with a fake DynamoDB (no Docker needed)."""
import time, unittest
from unittest import mock

from botocore.exceptions import ClientError
from fastapi.testclient import TestClient

from decision_service import main, stepup

KEY, OTP = b"test-only-key", "123456"


def condition_failed():
    return ClientError({"Error": {"Code": "ConditionalCheckFailedException"}}, "Write")


class FakeDdb:
    def __init__(self, blocked=False):
        self.used, self.devices, self.blocked = set(), set(), blocked

    def put_item(self, **kw):
        jti = kw["Item"]["jti"]["S"]
        if jti in self.used:
            raise condition_failed()
        self.used.add(jti)

    def update_item(self, **kw):
        if self.blocked:
            raise condition_failed()
        self.devices.update(kw["ExpressionAttributeValues"][":d"]["SS"])


class TokenChecks(unittest.TestCase):
    def test_round_trip(self):
        t = stepup.sign("tok_1", "dev_1", "c1", 1000, 300, KEY)
        self.assertEqual(stepup.verify(t, 1100, KEY)["dev"], "dev_1")

    def test_rejects(self):
        t = stepup.sign("tok_1", "dev_1", "c1", 1000, 300, KEY)
        body, sig = t.split(".")
        swapped = stepup.sign("tok_1", "dev_EVIL", "c1", 1000, 300, KEY).split(".")[0] + "." + sig
        for bad, now, key in ((t, 1301, KEY),            # expired
                              (t, 1100, b"other"),       # wrong secret
                              (swapped, 1100, KEY),      # wrong device: body changed, old signature
                              ("garbage", 1100, KEY), ("a.b.c", 1100, KEY), (body + ".", 1100, KEY)):
            with self.assertRaises(stepup.InvalidChallenge):
                stepup.verify(bad, now, key)

    def test_otp_stub(self):
        self.assertTrue(stepup.otp_ok("123456", "123456"))
        self.assertFalse(stepup.otp_ok("123456", ""))   # unset code never matches


@mock.patch.object(main, "STEPUP_SECRET", KEY)
@mock.patch.object(main, "STEPUP_OTP", OTP)
class VerifyEndpoint(unittest.TestCase):
    def setUp(self):
        self.api, self.ddb = TestClient(main.app), FakeDdb()   # no "with": lifespan (AWS) never runs
        main.S.ddb_admin = self.ddb

    def token(self, now=None):
        return stepup.sign("tok_1", "dev_new", "c1", now or time.time(), 300, KEY)

    def post(self, token, otp=OTP):
        return self.api.post("/v1/stepup/verify", json={"token": token, "otp": otp}).status_code

    def test_happy_path_trusts_device(self):
        self.assertEqual(self.post(self.token()), 200)
        self.assertEqual(self.ddb.devices, {"dev_new"})

    def test_reused_token_refused(self):
        t = self.token()
        self.assertEqual(self.post(t), 200)
        self.assertEqual(self.post(t), 400)

    def test_wrong_otp_burns_challenge(self):
        t = self.token()
        self.assertEqual(self.post(t, otp="000000"), 400)
        self.assertEqual(self.post(t), 400)             # no second guess with the right code
        self.assertEqual(self.ddb.devices, set())

    def test_expired(self):
        self.assertEqual(self.post(self.token(now=time.time() - 600)), 400)

    def test_blocked_card(self):
        main.S.ddb_admin = FakeDdb(blocked=True)        # condition "not blocked" fails
        self.assertEqual(self.post(self.token()), 400)

    def test_not_configured(self):
        with mock.patch.object(main, "STEPUP_SECRET", b""):
            self.assertEqual(self.post(self.token()), 503)


if __name__ == "__main__":
    unittest.main()
